// src/hooks/useBookManagement.js

import { useState } from 'react';
import axios from 'axios'; 

// URL base de tu API (Asegúrate de que coincida con tu server.js)
const API_BASE_URL = 'http://localhost:5000/api/books'; 

export const useBookManagement = () => {
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState(null);
    const [successMessage, setSuccessMessage] = useState(null);

    /**
     * Función para registrar un libro.
     * @param {FormData} bookFormData - Objeto FormData que contiene todos los campos y archivos.
     * @returns {Object} {success: boolean, id_libro: number}
     */
    const registerBook = async (bookFormData) => {
        setIsLoading(true);
        setError(null);
        setSuccessMessage(null);
        
        try {
            // Llama al endpoint POST /api/books/register
            const response = await axios.post(`${API_BASE_URL}/register`, bookFormData, {
                // Si estás usando JWT para rutas protegidas, debes incluirlo aquí.
                // Si usaste el useAuth.js anterior, axios debería tener el token globalmente:
                // headers: { Authorization: `Bearer ${localStorage.getItem('authToken')}` }
            });

            // Respuesta exitosa: 201 Created
            setSuccessMessage(response.data.message || "Libro registrado exitosamente.");
            setIsLoading(false);
            
            return { 
                success: true, 
                id_libro: response.data.id_libro 
            };

        } catch (err) {
            setIsLoading(false);
            
            // Extraer el mensaje de error del backend
            const backendMessage = err.response?.data?.message || "Error de conexión o error desconocido.";
            setError(backendMessage);
            
            console.error("Error al registrar el libro:", err);

            return { 
                success: false, 
                error: backendMessage 
            };
        }
    };

    return {
        registerBook,
        isLoading,
        error,
        successMessage,
        setError, 
        setSuccessMessage 
    };
};
